"use strict";function initAddLeaveDeduction(){$(".addLeavededuction").click(function(){var n=$(this).attr("data-id"),t=$(this).attr("data-annualbalance");$("#EmpId").val(n);$("#annualBalance").text(t);$("#insertform").dialog("open")})}function query(){$.ajax({url:_global.root+"Report/ListLateInEarlyOut",type:"POST",dataType:"html",data:$(".card-container-base .form-filter").serialize(),beforeSend:function(){$(".loading-process").fadeIn(300)},success:function(n){$("#list-detail").html(n);initAddLeaveDeduction();floatThead("table#data")},error:function(){alert(_messages.errorTryAgain)},complete:function(){$(".loading-process").fadeOut(300)}})}function submitForm(n){$("#IsExportExcel").val(n)}$(document).ready(function(){query();$("#submit").on("click",function(){query()});$("#insertform").dialog({modal:!0,autoOpen:!1,width:"auto",height:"auto",open:function(){$("#TotalDays").val("0.5");initDatePicker()},show:{effect:"blind",duration:200},hide:{effect:"blind",duration:100}});$("#insertform form").submit(function(n){n.preventDefault();$.post(_global.root+"AnnualLeave/AddLeaveDeduction",{empId:$("#EmpId").val(),totalDays:$("#TotalDays").val(),deductDate:$("#DeductDate").val(),description:$("#Description").val(),isAnnual:$("#IsAnnual").prop("checked")},function(n){n.IsSuccessful?($("#insertform").dialog("close"),document.location=_global.root+"report/LateInEarlyOut"):alert(n.Message)})});$("#cancel").click(function(){$("#insertform").dialog("close")})});$(document).ready(function(){initAutocomplete("#Employee","#EmployeeId");$("form").submit(function(){var n=$("#Employee").val();return n.length===0&&$("#EmployeeId").val(-1),!0})});